create table public.study_questions (
 id integer primary key,
 track text not null check (track in ('Step 1', 'Step 2 CK')),
 stage text not null,
 mode text not null check (mode in ('practice', 'mock')),
 topic text not null,
 stem text not null,
 options jsonb not null check (jsonb_array_length(options) = 4),
 answer integer not null check (answer between 0 and 3),
 reason text not null,
 tutor jsonb not null check (jsonb_array_length(tutor) = 4)
);
alter table public.study_questions enable row level security;
revoke all on public.study_questions from anon, authenticated;
grant select on public.study_questions to authenticated;
create policy "Signed-in students can read questions" on public.study_questions
 for select to authenticated using ((select auth.uid()) is not null and coalesce((auth.jwt()->>'is_anonymous')::boolean, false) = false);

create table public.study_progress (
 user_id uuid primary key references auth.users(id) on delete cascade,
 state jsonb not null check (jsonb_typeof(state) = 'object'),
 revision bigint not null default 1 check (revision > 0)
);
alter table public.study_progress enable row level security;
revoke all on public.study_progress from anon, authenticated;
grant select, insert, update on public.study_progress to authenticated;
create policy "Read own study progress" on public.study_progress for select to authenticated
 using ((select auth.uid()) = user_id);
create policy "Create own study progress" on public.study_progress for insert to authenticated
 with check ((select auth.uid()) = user_id);
create policy "Update own study progress" on public.study_progress for update to authenticated
 using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);

insert into public.study_questions
select * from jsonb_populate_recordset(null::public.study_questions, $questions$
[{"id":8,"track":"Step 1","stage":"fundamentos","mode":"practice","topic":"Cell signaling","stem":"A hormone binds a Gs-coupled receptor. Which intracellular change follows?","options":["Decreased cAMP","Increased cAMP","Opening of a nuclear receptor","Direct activation of a ligand-gated chloride channel"],"answer":1,"reason":"A subunidade Gs ativa a adenilato ciclase, aumentando o AMPc.","tutor":["A queda de AMPc é compatível com ativação de Gi.","Gs ativa a adenilato ciclase, elevando o AMPc.","O receptor descrito pertence à família dos receptores acoplados à proteína G.","O efeito direto descrito seria próprio de um canal regulado por ligante."]},{"id":9,"track":"Step 1","stage":"fundamentos","mode":"practice","topic":"Enzyme kinetics","stem":"A reversible competitive inhibitor is added to an enzyme assay. What happens to apparent Km and Vmax?","options":["Both decrease","Both increase","Km increases and Vmax is unchanged","Km is unchanged and Vmax decreases"],"answer":2,"reason":"O substrato compete com o inibidor. O Km aparente sobe, e concentrações suficientemente altas de substrato ainda alcançam o mesmo Vmax.","tutor":["A competição pode ser superada com mais substrato, preservando Vmax.","Vmax continua alcançável em alta concentração de substrato.","É necessário mais substrato para alcançar metade de Vmax, aumentando o Km aparente.","Queda de Vmax com Km constante descreve a inibição não competitiva pura."]},{"id":10,"track":"Step 1","stage":"fundamentos","mode":"practice","topic":"Genetics","stem":"Two unaffected parents are heterozygous for the same autosomal recessive disorder. What is the probability that their next child is affected?","options":["25%","0%","50%","75%"],"answer":0,"reason":"A criança precisa herdar uma variante de cada progenitor. O produto de 1/2 por 1/2 é 1/4.","tutor":["Cada progenitor tem uma chance de 1/2 de transmitir a variante. Multiplique as duas probabilidades.","Ambos podem transmitir a variante.","50% é a probabilidade de herdar exatamente uma das duas variantes parentais.","75% é a probabilidade de não ser afetado nesse cruzamento."]},{"id":11,"track":"Step 1","stage":"fundamentos","mode":"practice","topic":"Acid–base physiology","stem":"Blood gas shows pH 7.25, low bicarbonate and low PCO₂. Which primary disturbance best explains the acidemia?","options":["Respiratory alkalosis","Metabolic alkalosis","Respiratory acidosis","Metabolic acidosis"],"answer":3,"reason":"O bicarbonato baixo explica a acidemia. A redução da PCO₂ é compatível com compensação respiratória.","tutor":["A PCO₂ baixa pode ser compensatória e não explica a acidemia.","Alcalose metabólica envolve elevação primária do bicarbonato.","Acidose respiratória envolve aumento primário da PCO₂.","O bicarbonato baixo é a alteração primária que explica a acidemia."]},{"id":12,"track":"Step 1","stage":"fundamentos","mode":"mock","topic":"Acid–base physiology","stem":"After acute hypoventilation, a blood gas shows acidemia and an elevated PCO₂. Which primary disturbance is present?","options":["Metabolic acidosis","Respiratory acidosis","Metabolic alkalosis","Respiratory alkalosis"],"answer":1,"reason":"A retenção de CO₂ por hipoventilação causa acidose respiratória.","tutor":["Acidose metabólica envolve queda primária do bicarbonato.","Hipoventilação retém CO₂, elevando a PCO₂ e reduzindo o pH.","Alcalose implica uma alteração que eleva o pH.","Alcalose respiratória envolve queda primária da PCO₂."]},{"id":13,"track":"Step 1","stage":"fundamentos","mode":"mock","topic":"Genetics","stem":"A heterozygous parent has a fully penetrant autosomal dominant disorder. The other parent does not carry the variant. What is the probability the child inherits it?","options":["100%","25%","0%","50%"],"answer":3,"reason":"O progenitor heterozigoto transmite um de seus dois alelos com probabilidade de 1/2.","tutor":["O progenitor heterozigoto pode transmitir o alelo sem a variante.","25% seria compatível com certos cruzamentos recessivos.","A variante pode ser transmitida pelo progenitor heterozigoto.","Cada um dos dois alelos do progenitor heterozigoto tem a mesma chance de transmissão."]},{"id":14,"track":"Step 1","stage":"fundamentos","mode":"mock","topic":"Membrane potential","stem":"Extracellular potassium increases while intracellular potassium remains stable. How does the potassium equilibrium potential change?","options":["It becomes less negative","It becomes more negative","It is unchanged","It becomes identical to the sodium equilibrium potential"],"answer":0,"reason":"A elevação do potássio extracelular reduz o gradiente de concentração. O potencial de equilíbrio do potássio torna-se menos negativo.","tutor":["Mais potássio fora da célula reduz o gradiente, tornando Eₖ menos negativo.","Um gradiente maior, e não menor, deslocaria Eₖ na direção mais negativa.","O potencial de equilíbrio depende da razão entre as concentrações externa e interna.","Alterar o potássio externo não iguala necessariamente Eₖ ao potencial do sódio."]},{"id":15,"track":"Step 1","stage":"fundamentos","mode":"mock","topic":"Cell signaling","stem":"Acetylcholine activates M2 muscarinic receptors in sinoatrial nodal cells. Which G protein mediates inhibition of adenylyl cyclase?","options":["Gs","Gq","Gi","G12"],"answer":2,"reason":"O receptor M2 acopla-se a Gi, reduzindo a atividade da adenilato ciclase.","tutor":["Gs estimula a adenilato ciclase.","Gq é associado à ativação de fosfolipase C.","O receptor muscarínico M2 ativa Gi, que inibe a adenilato ciclase.","G12 não é o mediador descrito para esse receptor."]},{"id":0,"track":"Step 1","stage":"metodos","mode":"practice","topic":"Sensitivity","stem":"A screening test identifies 72 of 90 people who truly have a condition. What is its sensitivity?","options":["72%","80%","90%","18%"],"answer":1,"reason":"Sensibilidade é a proporção dos indivíduos com a condição que têm teste positivo. Aqui, 72 ÷ 90 = 80%.","tutor":["72 é o número de verdadeiros positivos.","Divida 72 por 90, o total de pessoas com a condição.","90 é o número de pessoas com a condição.","18 é o número de falsos negativos, não uma porcentagem."]},{"id":1,"track":"Step 1","stage":"metodos","mode":"practice","topic":"Specificity","stem":"Of 200 participants without the condition, 180 have a negative test. What is the specificity?","options":["10%","80%","90%","95%"],"answer":2,"reason":"Especificidade é a proporção de verdadeiros negativos entre os indivíduos sem a condição. Aqui, 180 ÷ 200 = 90%.","tutor":["10% é a proporção de falsos positivos.","180 de 200 correspondem a 90%.","Divida 180 verdadeiros negativos por 200 participantes sem a condição.","95% corresponderia a 190 de 200."]},{"id":2,"track":"Step 1","stage":"metodos","mode":"practice","topic":"Positive predictive value","stem":"A test is positive in 60 people. Of these, 45 truly have the condition. What is the positive predictive value?","options":["75%","25%","60%","45%"],"answer":0,"reason":"O valor preditivo positivo usa como denominador todos os resultados positivos. Aqui, 45 ÷ 60 = 75%.","tutor":["45 dos 60 resultados positivos são verdadeiros positivos.","25% é a proporção de falsos positivos entre os resultados positivos.","60 é o número absoluto de resultados positivos.","45 é o número absoluto de verdadeiros positivos."]},{"id":3,"track":"Step 1","stage":"metodos","mode":"practice","topic":"Case-control studies","stem":"Investigators recruit adults with a rare condition and adults without it, then compare their prior exposures. What is the study design?","options":["Cross-sectional study","Randomized trial","Prospective cohort","Case-control study"],"answer":3,"reason":"O recrutamento parte do desfecho. Depois, os pesquisadores comparam a exposição prévia entre casos e controles.","tutor":["Um estudo transversal mede exposição e desfecho em um recorte temporal.","Os pesquisadores não atribuíram as exposições aleatoriamente.","Uma coorte prospectiva seleciona participantes antes da ocorrência do desfecho em estudo.","A seleção começa pelo desfecho e compara exposições anteriores."]},{"id":16,"track":"Step 1","stage":"metodos","mode":"mock","topic":"Screening tests","stem":"Among 120 individuals with a condition, 96 have a positive screening result. What is the false-negative rate among individuals with the condition?","options":["80%","24%","96%","20%"],"answer":3,"reason":"São 24 falsos negativos em 120 pessoas com a condição, ou 20%.","tutor":["80% é a sensibilidade do teste.","24 é o número absoluto de falsos negativos.","96 é o número absoluto de verdadeiros positivos.","Dos 120 indivíduos com a condição, 24 tiveram resultado negativo, ou 20%."]},{"id":17,"track":"Step 1","stage":"metodos","mode":"mock","topic":"Predictive values","stem":"Of 160 people with a negative test, 152 truly do not have the condition. What is the negative predictive value?","options":["95%","5%","80%","8%"],"answer":0,"reason":"O valor preditivo negativo é a proporção de verdadeiros negativos entre todos os testes negativos: 152 ÷ 160.","tutor":["152 de 160 resultados negativos são verdadeiros negativos.","5% é a proporção complementar, de falsos negativos entre os resultados negativos.","80% equivaleria a 128 de 160.","8 é o número de falsos negativos, não uma porcentagem."]},{"id":18,"track":"Step 1","stage":"metodos","mode":"mock","topic":"Study design","stem":"Investigators classify participants by exposure at enrollment and then observe new diagnoses over five years. Which design is this?","options":["Case-control study","Prospective cohort study","Cross-sectional study","Case series"],"answer":1,"reason":"A coorte prospectiva parte da exposição e observa a ocorrência de novos desfechos ao longo do tempo.","tutor":["Um caso-controle começa pela seleção segundo o desfecho.","A exposição é medida no início e os novos desfechos são observados durante o seguimento.","O estudo transversal não acompanha a incidência por cinco anos.","Uma série de casos descreve casos em vez de comparar grupos segundo exposição."]},{"id":19,"track":"Step 1","stage":"metodos","mode":"mock","topic":"Prevalence","stem":"A disease becomes less common in a population. Sensitivity and specificity of an unchanged screening test stay constant. What usually happens to positive predictive value?","options":["It increases","It is fixed by specificity","It decreases","It always equals sensitivity"],"answer":2,"reason":"Com prevalência menor, os verdadeiros positivos representam uma fração menor de todos os resultados positivos quando sensibilidade e especificidade permanecem constantes.","tutor":["Com menos casos, os verdadeiros positivos representam uma parcela menor dos testes positivos.","O valor preditivo depende também da prevalência.","A queda de prevalência reduz o valor preditivo positivo quando as demais características ficam constantes.","Sensibilidade e valor preditivo positivo têm denominadores diferentes."]},{"id":20,"track":"Step 2 CK","stage":"clinica","mode":"practice","topic":"Pediatrics · Gastroenterology","stem":"An infant has progressive nonbilious projectile vomiting after feeds. The infant is hungry again after vomiting, and an olive-shaped mass is palpable. What is the most likely diagnosis?","options":["Midgut volvulus","Hypertrophic pyloric stenosis","Intussusception","Hirschsprung disease"],"answer":1,"reason":"Vômitos em jato sem bile e uma massa em oliva apontam para estenose hipertrófica do piloro.","tutor":["O volvo intestinal costuma produzir vômitos biliosos.","Vômitos em jato sem bile e massa em oliva favorecem estenose hipertrófica do piloro.","A invaginação costuma causar dor episódica e pode mostrar sinal de alvo na ultrassonografia.","A doença de Hirschsprung costuma cursar com constipação e distensão."]},{"id":21,"track":"Step 2 CK","stage":"clinica","mode":"practice","topic":"Internal medicine · Hematology","stem":"A patient with heavy menstrual bleeding has microcytosis and a low serum ferritin. What is the most likely cause of anemia?","options":["Vitamin B12 deficiency","Iron deficiency","Acute hemolysis","Folate deficiency"],"answer":1,"reason":"Ferritina baixa é compatível com redução dos estoques de ferro. A perda crônica de sangue e a microcitose reforçam o diagnóstico.","tutor":["Deficiência de B12 costuma cursar com macrocitose.","Microcitose e ferritina baixa, com perda menstrual crônica, apontam para deficiência de ferro.","O enunciado indica depleção de ferro e não fornece sinais típicos de hemólise.","A deficiência de folato costuma cursar com macrocitose."]},{"id":22,"track":"Step 2 CK","stage":"clinica","mode":"practice","topic":"Pediatrics · Respiratory","stem":"A child has a barking cough, hoarseness and inspiratory stridor after two days of coryza. What is the most likely diagnosis?","options":["Bronchiolitis","Asthma","Viral croup","Pneumothorax"],"answer":2,"reason":"Tosse ladrante, rouquidão e estridor inspiratório após pródromo viral são típicos de crupe.","tutor":["Bronquiolite acomete as vias aéreas inferiores e costuma causar sibilos.","Asma costuma causar sibilância expiratória. Estridor e rouquidão apontam para vias aéreas superiores.","Tosse ladrante, rouquidão e estridor inspiratório após coriza favorecem crupe.","Pneumotórax não explica o padrão de tosse ladrante após pródromo viral."]},{"id":23,"track":"Step 2 CK","stage":"clinica","mode":"practice","topic":"Internal medicine · Respiratory","stem":"Spirometry shows a reduced FEV₁/FVC ratio before a bronchodilator. Which ventilatory pattern is present at baseline?","options":["Obstructive","Restrictive confirmed by spirometry alone","Normal","Isolated diffusion impairment"],"answer":0,"reason":"Uma razão FEV₁/FVC reduzida caracteriza obstrução ao fluxo aéreo.","tutor":["A redução de FEV₁ em proporção à FVC caracteriza um padrão obstrutivo.","A confirmação de restrição exige demonstrar redução da capacidade pulmonar total.","Uma razão abaixo do limite inferior de normalidade indica alteração.","Esse achado não mede difusão, que exige teste próprio."]},{"id":24,"track":"Step 2 CK","stage":"clinica","mode":"mock","topic":"Pediatrics · Gastroenterology","stem":"An infant has repeated episodes of intense crying and draws the knees toward the abdomen. Between episodes the infant appears fatigued. Ultrasound shows concentric rings. What diagnosis is most likely?","options":["Pyloric stenosis","Gastroesophageal reflux","Hirschsprung disease","Intussusception"],"answer":3,"reason":"Dor intermitente e imagem em alvo favorecem invaginação intestinal.","tutor":["Estenose do piloro costuma causar vômito em jato após alimentação.","Refluxo não explica a imagem ultrassonográfica em anéis concêntricos.","Hirschsprung costuma cursar com constipação precoce e distensão.","Dor episódica e imagem em alvo são características de invaginação."]},{"id":25,"track":"Step 2 CK","stage":"clinica","mode":"mock","topic":"Internal medicine · Hematology","stem":"A patient with macrocytosis has paresthesias and impaired vibration sense. Which nutritional deficiency best explains both findings?","options":["Iron","Vitamin B12","Vitamin C","Folate"],"answer":1,"reason":"A deficiência de vitamina B12 pode causar anemia macrocítica e acometimento neurológico com perda da sensibilidade vibratória.","tutor":["A deficiência de ferro costuma causar microcitose.","A deficiência de B12 explica a macrocitose e os sintomas neurológicos.","A deficiência de vitamina C é associada ao escorbuto.","Deficiência de folato causa macrocitose, mas não explica o padrão neurológico característico de B12."]},{"id":26,"track":"Step 2 CK","stage":"clinica","mode":"mock","topic":"Pediatrics · Respiratory","stem":"A six-month-old develops rhinorrhea, then cough, diffuse wheezing and fine crackles during the first such episode. Which diagnosis is most likely?","options":["Viral bronchiolitis","Viral croup","Pertussis","Epiglottitis"],"answer":0,"reason":"Em lactente, pródromo viral seguido de sibilância difusa e estertores favorece bronquiolite.","tutor":["Primeiro episódio de sibilância difusa em lactente após coriza favorece bronquiolite.","Crupe costuma causar tosse ladrante e estridor inspiratório.","Coqueluche costuma causar crises paroxísticas de tosse.","Epiglotite pode causar disfagia, salivação e estridor, em vez de sibilância difusa."]},{"id":27,"track":"Step 2 CK","stage":"clinica","mode":"mock","topic":"Internal medicine · Respiratory","stem":"A patient has sudden dyspnea after blunt chest trauma. Breath sounds are markedly decreased and percussion is hyperresonant on one side. Which finding best explains these signs?","options":["Pleural fluid","Pulmonary edema","Air in the pleural space","Lobar consolidation"],"answer":2,"reason":"O ar pleural reduz a transmissão dos sons respiratórios e produz hiperressonância à percussão.","tutor":["Líquido pleural causa macicez à percussão.","Edema pulmonar costuma causar estertores e não hiperressonância unilateral.","Ar no espaço pleural explica hiperressonância e redução unilateral dos sons respiratórios.","Consolidação tende a produzir macicez."]},{"id":4,"track":"Step 2 CK","stage":"evidencia","mode":"practice","topic":"Absolute risk reduction","stem":"In a randomized trial, an outcome occurs in 12% of controls and 8% of participants assigned to the intervention. What is the absolute risk reduction?","options":["33 percentage points","4 percentage points","8 percentage points","12 percentage points"],"answer":1,"reason":"A redução absoluta do risco é a diferença entre os riscos dos grupos. Aqui, 12% − 8% = 4 pontos percentuais.","tutor":["33% é aproximadamente a redução relativa de risco.","Subtraia 8% de 12% para obter quatro pontos percentuais.","8% é o risco no grupo intervenção.","12% é o risco no grupo controle."]},{"id":5,"track":"Step 2 CK","stage":"evidencia","mode":"practice","topic":"Number needed to treat","stem":"An intervention reduces the absolute risk of an outcome by 5 percentage points over one year. What is the number needed to treat over that period?","options":["5","10","20","50"],"answer":2,"reason":"O número necessário para tratar é o inverso da redução absoluta do risco em proporção. Aqui, 1 ÷ 0,05 = 20.","tutor":["5 é a redução expressa em pontos percentuais.","Um NNT de 10 corresponderia a uma redução absoluta de 10 pontos percentuais.","O inverso de 0,05 resulta em 20.","Um NNT de 50 corresponderia a uma redução absoluta de dois pontos percentuais."]},{"id":6,"track":"Step 2 CK","stage":"evidencia","mode":"practice","topic":"Confidence intervals","stem":"A study reports a relative risk of 0.82 with a 95% confidence interval of 0.64 to 1.05. Which statement is supported?","options":["The interval includes the null value.","The interval excludes the null value.","The point estimate is above 1.","The result establishes that the risks are equal."],"answer":0,"reason":"O valor nulo para uma razão de riscos é 1. Como o intervalo inclui 1, o resultado é compatível com ausência de diferença.","tutor":["O intervalo vai de 0,64 a 1,05 e contém 1, o valor nulo da razão de riscos.","O limite superior ultrapassa 1.","A estimativa pontual de 0,82 é menor que 1.","Incluir o valor nulo indica compatibilidade com ausência de diferença, sem estabelecer igualdade."]},{"id":7,"track":"Step 2 CK","stage":"evidencia","mode":"practice","topic":"Intention to treat","stem":"In a randomized trial, some participants stop their assigned treatment. In an intention-to-treat analysis, how should they be grouped?","options":["By treatment received","By adherence level","Exclude participants who stopped treatment","By original random assignment"],"answer":3,"reason":"A análise por intenção de tratar mantém os participantes no grupo da alocação original.","tutor":["Agrupar pelo tratamento recebido abandona a comparação pela alocação original.","Agrupar por adesão modifica os grupos depois da randomização.","Excluir quem interrompeu o tratamento abandona a análise da alocação original.","Todos permanecem no grupo para o qual foram randomizados."]},{"id":28,"track":"Step 2 CK","stage":"evidencia","mode":"mock","topic":"Clinical evidence","stem":"An outcome occurs in 20% of controls and 10% of treated patients. What is the relative risk of the outcome in the treatment group?","options":["0.50","0.10","2.00","0.90"],"answer":0,"reason":"O risco relativo divide o risco no grupo tratado pelo risco no controle: 10% ÷ 20% = 0,50.","tutor":["O risco no grupo tratado é metade do risco no controle: 0,10 ÷ 0,20.","0,10 é o risco no grupo tratado, antes de dividir pelo risco do controle.","2,00 corresponde à razão com os grupos invertidos.","0,90 é a proporção sem o desfecho no grupo tratado."]},{"id":29,"track":"Step 2 CK","stage":"evidencia","mode":"mock","topic":"Clinical evidence","stem":"Over six months, an adverse event occurs in 7% of treated patients and 3% of controls. What is the number needed to harm over this period?","options":["4","14","10","25"],"answer":3,"reason":"O aumento absoluto de risco é 0,04. Seu inverso é 25.","tutor":["4 é o aumento absoluto de risco em pontos percentuais.","14 é aproximadamente o inverso do risco no grupo tratado, sem descontar o controle.","Um NNH de 10 corresponderia a um aumento absoluto de 10 pontos percentuais.","O aumento absoluto é 0,04, cujo inverso é 25."]},{"id":30,"track":"Step 2 CK","stage":"evidencia","mode":"mock","topic":"Clinical evidence","stem":"A study reports an odds ratio of 1.50, with a 95% confidence interval of 1.15 to 1.96. Which interpretation is supported?","options":["The interval includes the null value","The interval is entirely above the null value","The point estimate shows lower odds","The result establishes causality"],"answer":1,"reason":"O valor nulo da razão de chances é 1. Todo o intervalo está acima de 1.","tutor":["O limite inferior é 1,15, já acima de 1.","Todo o intervalo está acima de 1, o valor nulo.","Uma razão de chances de 1,50 indica chances maiores na comparação informada.","A estimativa e seu intervalo, isoladamente, não estabelecem causalidade."]},{"id":31,"track":"Step 2 CK","stage":"evidencia","mode":"mock","topic":"Clinical evidence","stem":"During a randomized trial, participants with poor outcomes are disproportionately lost from the intervention group. Which bias is the main concern?","options":["Recall bias","Lead-time bias","Attrition bias","Interviewer bias"],"answer":2,"reason":"Perdas de seguimento relacionadas ao desfecho e desiguais entre grupos podem distorcer o efeito estimado.","tutor":["Viés de memória envolve diferença na recordação de exposições ou eventos.","Viés de tempo de antecipação decorre de diagnóstico mais precoce sem necessariamente mudar a sobrevida real.","Perdas desiguais e relacionadas ao desfecho podem enviesar o resultado.","Viés do entrevistador depende da forma de coletar a informação."]}]
$questions$);
